function b(g,i){const n=new Map;for(const t of g){const o=t.r.candidates[0].party;n.has(o)||n.set(o,[]),n.get(o).push({...t})}const a=[...n].map(([t,o])=>({party:t,nodes:o.sort((s,r)=>r.radius-s.radius),votes:o.reduce((s,r)=>s+r.r.total,0)})).sort((t,o)=>o.votes-t.votes);if(!a.length)return[];const h=20,l=Math.max(1,i.width-h*(a.length-1)),e=Math.min(110,l/a.length*.7),u=a.reduce((t,o)=>t+o.votes,0),x=Math.max(1,i.height-34);for(const t of a)t.width=e+(l-e*a.length)*t.votes/u;function m(t,o,s=!1){let r=0,w=0,f=0;for(const p of t.nodes){const k=p.radius*o,d=k*2+6;if(d>t.width)return 1/0;r&&r+d>t.width&&(w+=f,r=0,f=0),f=Math.max(f,d),s&&(p.x=r+d/2,p.y=w+f/2,p.radius=k),r+=d}return w+f}let c=0,y=Math.max(i.width,i.height)/70;for(let t=0;t<28;t++){const o=(c+y)/2;a.every(s=>m(s,o)<=x)?c=o:y=o}let v=i.x;const M=[];for(const t of a){const o=m(t,c);m(t,c,!0);for(const s of t.nodes)s.x+=v,s.y+=i.y+34+(x-o)/2,s.groupX=v+t.width/2,M.push(s);v+=t.width+h}return M}function F(g){const i=g.filter(e=>Number.isFinite(e.total)&&e.total>0).slice().sort((e,u)=>u.total-e.total),n=i.reduce((e,u)=>e+u.total,0);let a=0,h=0;const l=i.map((e,u)=>(a+=e.total,!h&&a>=n/2&&(h=u+1),{r:e,rank:u+1,share:e.total/n*100,cumulative:a/n*100}));return{rows:l,total:n,halfCount:h,topFive:l[Math.min(4,l.length-1)]?.cumulative||0}}export{b as p,F as r};
